extends Node

func _ready() -> void:
	var packed = load("res://main.tscn")
	if packed == null:
		print("BENCH FAIL: main.tscn does not load")
	else:
		var main = packed.instantiate()
		var label = main.get_node_or_null("ScoreLabel")
		if label == null:
			print("BENCH FAIL: no ScoreLabel under Main")
		elif not label is Label:
			print("BENCH FAIL: ScoreLabel is a %s, not a Label" % label.get_class())
		elif label.text != "Score: 0":
			print("BENCH FAIL: ScoreLabel text is %s" % label.text)
		elif label.position.distance_to(Vector2(16, 16)) > 0.5:
			print("BENCH FAIL: ScoreLabel is at %s" % label.position)
		else:
			print("BENCH PASS")
		main.free()
	get_tree().quit()

